/* PipeReply */
typedef struct { uint8_t sink; uint32_t bytes; uint32_t crc32; uint32_t packets; uint32_t full; } zd1h_pipe_reply_t;
/* BootState: Which system slot the module starts (the MCU keeps the choice in the EEPROM and tells the boot stub at every boot, SPI reg 0xC4: `docs/module/storage.md`). */
typedef struct { uint8_t unused_; } zd1h_boot_state_t;
/* Boot: Change which slot the module starts (`BootOp`); `restart`: power-cycle the module now so it does. */
typedef struct { uint8_t op; uint8_t slot; bool restart; } zd1h_boot_t;
/* Update: Update the network module's system (`docs/module/updater.md`): BEGIN tells its updater over SPI (reg 0xC5) and points the bulk pipe at the module (sink MODULE, from zero); the image then goes to the bulk endpoint, `size` bytes, and `UpdateStatus` says how far it is. The module must run our OS (a slot or the rescue). */
typedef struct { uint8_t op; uint32_t size; uint16_t sha256_len; uint8_t sha256[32]; char id[65]; uint32_t baud; } zd1h_update_t;
/* UpdateStatus: How far the module's update is. */
typedef struct { uint8_t unused_; } zd1h_update_status_t;
/* UpdateReply */
typedef struct { uint8_t state; uint32_t sent; uint32_t on_wire; uint32_t size; uint8_t slot; char text[97]; } zd1h_update_reply_t;
/* Console: Open the module's console for this host (POLL's CONSOLE records: the module doc), starting afresh, or close it. The console's line is the updater's while an update runs: nothing passes then. */
typedef struct { bool open; } zd1h_console_t;
/* ConsoleWrite: Bytes for the module's console (open: `Console`): as many as the MCU's send ring takes now (`taken`); the host sends the rest again. `Error ARG` while it isn't open. */
typedef struct { uint16_t data_len; uint8_t data[240]; } zd1h_console_write_t;
/* ConsoleReply */
typedef struct { bool open; uint16_t taken; uint32_t lost; } zd1h_console_reply_t;
/* PipeData: Data into the bulk pipe as if it came on the bulk endpoint: the emulator's build only (its USB carries EP0 only). `Error BUSY` while both buffers are full: send it again. */
typedef struct { uint16_t data_len; uint8_t data[240]; } zd1h_pipe_data_t;
/* BootReply */
typedef struct { uint8_t good; uint8_t next; uint8_t last; bool trial; uint8_t failed; } zd1h_boot_reply_t;
/* Prefs: The speaker's behaviour, kept in the EEPROM: switching to a USB stream by itself, how long a silent source keeps the amp on, the highest volume on every source. `change` says which fields to set (0: only read them). The amp's lock is `Amp`. */
typedef struct { uint8_t change; bool auto_switch; uint16_t amp_idle_s; uint8_t volume_cap; } zd1h_prefs_t;
/* PrefsReply */
typedef struct { bool auto_switch; bool amp_auto; uint16_t amp_idle_s; uint8_t volume_cap; } zd1h_prefs_reply_t;
/* Diag: The firmware's internals for debugging: protections, audio path, USB audio, the module's link, the remote. */
typedef struct { uint8_t unused_; } zd1h_diag_t;
/* DiagReply */
typedef struct { uint16_t adc4; uint16_t adc5; uint16_t adc6; bool fault; bool amp_fault; uint8_t n_temp; uint8_t n_adc4; uint8_t n_fault; uint8_t error; bool amp_unmuted; bool dsp_running; uint8_t dsp_in; bool spdif_locked; uint8_t dsp_volume; bool aux_jack; bool usb_vbus; uint8_t led; uint16_t ir_frames; uint8_t ir_addr; uint8_t ir_cmd; bool ir_toggle; uint32_t ir_ms; bool usb_streaming; uint32_t usb_rate; bool usb_mute; uint8_t usb_step; uint32_t usb_packets; bool hid; bool engine; bool clock_ok; uint16_t fill; bool primed; uint32_t underruns; uint32_t overruns; uint32_t dropped; uint32_t play_fps; uint32_t host_fps; uint32_t ratio; uint32_t nominal; bool net; uint8_t play; uint8_t pending_volume; uint32_t modcon_overruns; uint32_t amp_on_s; uint32_t amp_run_s; uint8_t heat_cap; bool usb_audible; uint16_t silent_s; uint32_t level; uint32_t level_floor; } zd1h_diag_reply_t;

/* ---- codec ---- */
enum { ZD1H_T_U8, ZD1H_T_U16, ZD1H_T_U32, ZD1H_T_BOOL, ZD1H_T_STR, ZD1H_T_BYTES };
typedef struct { uint8_t type; uint16_t max; uint16_t off; uint16_t len_off; } zd1h_field_t;
typedef struct { uint8_t id; uint8_t n; const zd1h_field_t *f; uint16_t size; } zd1h_msg_t;

/* the struct `s` as message `m` into out[cap]: the length, or -1 (doesn't fit, a length over its maximum) */
static inline int zd1h_encode(const zd1h_msg_t *m, const void *s, uint8_t *out, int cap){
    const uint8_t *p = (const uint8_t *)s;
    int n = 0;
    if(cap < 1) return -1;
    out[n++] = m->id;
    for(int i = 0; i < m->n; i++){
        const zd1h_field_t *f = &m->f[i];
        const uint8_t *v = p + f->off;
        uint32_t x = 0, l = 0;
        switch(f->type){
        case ZD1H_T_U8:   x = *v; l = 1; break;
        case ZD1H_T_BOOL: x = *(const bool *)v ? 1 : 0; l = 1; break;
        case ZD1H_T_U16:  x = *(const uint16_t *)v; l = 2; break;
        case ZD1H_T_U32:  x = *(const uint32_t *)v; l = 4; break;
        case ZD1H_T_STR:
            while(l < f->max && v[l]) l++;
            if(n + 1 + (int)l > cap) return -1;
            out[n++] = (uint8_t)l; memcpy(out + n, v, l); n += l;
            continue;
        default:          /* ZD1H_T_BYTES */
            l = *(const uint16_t *)(p + f->len_off);
            if(l > f->max || n + 2 + (int)l > cap) return -1;
            out[n++] = (uint8_t)l; out[n++] = (uint8_t)(l >> 8); memcpy(out + n, v, l); n += l;
            continue;
        }
        if(n + (int)l > cap) return -1;
        for(uint32_t k = 0; k < l; k++) out[n++] = (uint8_t)(x >> (8 * k));
    }
    return n;
}

/* message `m` from in[len] into the struct `s`: 0, or -1 (another id, a field cut short, a length over its
 * maximum). The compatibility rules (protocol/host/src/lib.rs): fields after the last one sent stay zero / empty (an
 * older peer), bytes after the fields we know are ignored (a newer peer's). */
static inline int zd1h_decode(const zd1h_msg_t *m, const uint8_t *in, int len, void *s){
    uint8_t *p = (uint8_t *)s;
    int k = 1;
    if(len < 1 || in[0] != m->id) return -1;
    memset(s, 0, m->size);
    for(int i = 0; i < m->n && k < len; i++){
        const zd1h_field_t *f = &m->f[i];
        uint8_t *v = p + f->off;
        int need = f->type == ZD1H_T_U16 ? 2 : f->type == ZD1H_T_U32 ? 4 : f->type == ZD1H_T_BYTES ? 2 : 1;
        if(k + need > len) return -1;
        uint32_t x = 0;
        for(int b = 0; b < need; b++) x |= (uint32_t)in[k + b] << (8 * b);
        k += need;
        switch(f->type){
        case ZD1H_T_U8:   *v = (uint8_t)x; break;
        case ZD1H_T_BOOL: if(x > 1) return -1; *(bool *)v = x != 0; break;
        case ZD1H_T_U16:  *(uint16_t *)v = (uint16_t)x; break;
        case ZD1H_T_U32:  *(uint32_t *)v = x; break;
        case ZD1H_T_STR:
            if(x > f->max || k + (int)x > len) return -1;
            memcpy(v, in + k, x); v[x] = 0; k += x;
            break;
        default:          /* ZD1H_T_BYTES */
            if(x > f->max || k + (int)x > len) return -1;
            memcpy(v, in + k, x); *(uint16_t *)(p + f->len_off) = (uint16_t)x; k += x;
            break;
        }
    }
    return 0;
}

